int journal_unmap_buffer(journal_t *journal, struct buffer_head *bh) {
    struct journal_head *jh;

    if (!buffer_journaled(bh))
        return 0;

    jh = get_journal_head(bh);
    if (!jh)
        return -EINVAL;

    lock_journal(journal);

    if (jh->b_jlist == BJ_Metadata || jh->b_jlist == BJ_Dirty) {
        jh->b_modified = 0;
        jh->b_jlist = BJ_None;
        unlock_journal(journal);
        return 0;
    }

    if (jh->b_transaction) {
        if (jh->b_transaction->t_state == T_RUNNING) {
            unlock_journal(journal);
            return -EBUSY;
        } else if (jh->b_transaction->t_state == T_COMMIT_Running) {
            jh->b_transaction->t_used = 1;
            jh->b_modified = 0;
            jh->b_jlist = BJ_None;
            unlock_journal(journal);
            return 0;
        }
    }

    unlock_journal(journal);
    return 0;
}

int journal_unmap_buffer(journal_t *journal, struct buffer_head *bh) {
    struct journal_head *jh;
    struct transaction_t *transaction;
    int ret = 0;

    if (!buffer_journalled(bh))
        return 0;

    jh = journal_grab_journal_head(bh);
    if (!jh)
        return -EINVAL;

    transaction = jh->b_transaction;
    spin_lock(&journal->j_list_lock);

    if (!transaction || transaction->t_state == T_LOCKED) {
        journal_unmap_ijhead(journal, bh, jh);
        jbd_debug(4, "Zapping buffer %p(%d)\n", bh, jh->b_blocknr);
        jbd_zap_buffer(journal, bh, jh);
    } else if (transaction->t_state == T_COMMIT_RND) {
        jbd_debug(4, "Adding to commit list for buffer %p\n", bh);
        journal_attach_to_commit_transaction(transaction, bh, jh);
    } else if (transaction == journal->j_running_transaction) {
        jbd_debug(4, "Disposing of buffer %p in running transaction\n", bh);
        journal_dispose_buffer(transaction, bh, jh);
    } else {
        jbd_debug(4, "Buffer %p has unknown transaction state %d\n", bh, transaction->t_state);
        ret = -EIO;
    }

    spin_unlock(&journal->j_list_lock);
    clear_buffer_journalled(bh);
    journal_put_journal_head(jh);
    return ret;
}

int journal_unmap_buffer(journal_t *journal, struct buffer_head *bh) {
    struct journal_head *jh;
    transaction_t *t;

    if (!buffer_journaled(bh))
        return 0;

    jh = journal_lock_journal_head(journal, bh);
    if (!jh)
        return -1;

    t = jh->t;
    if (!t) {
        journal_zap_buffer(journal, bh);
    } else if (t->state == TRANSACTION_COMMITTING) {
        journal_attach_buffer_to_committing(journal, jh);
    } else if (t->state == TRANSACTION_RUNNING) {
        journal_dispose_buffer(journal, jh);
    } else {
        journal_clear_dirty(journal, jh);
        journal_unlock_journal_head(jh);
        return 1;
    }

    journal_unlock_journal_head(jh);
    return 0;
}

int journal_unmap_buffer(journal_t *journal, struct buffer_head *bh) {
    struct journal_head *jh;
    int ret = 0;

    if (!buffer_journaled(bh))
        return 0;

    jh = get_journal_head(bh);
    if (!jh)
        return -EINVAL;

    spin_lock(&journal->j_list_lock);
    if (jh->b_transaction) {
        if (jh->b_transaction == journal->j_committing_transaction) {
            jh->b_buffer = NULL;
            jh->b_transaction = NULL;
        } else if (jh->b_transaction == journal->j_running_transaction) {
            jh->b_buffer = NULL;
            jh->b_transaction = NULL;
        } else {
            jh->b_dirty = 0;
            jh->b_transaction = NULL;
        }
    }

    clear_bit(BH_Journaled, &bh->b_state);
    spin_unlock(&journal->j_list_lock);

    return ret;
}

int journal_unmap_buffer(journal_t *journal, struct buffer_head *bh) {
    struct journal_head *jh;
    int ret = 0;

    if (!buffer_journaled(bh))
        return 0;

    jh = journal_get_jhead(journal, bh->b_blocknr);
    if (!jh)
        return -EINVAL;

    jbd_lock_journal(journal);

    if (jh->b_transaction) {
        if (jh->b_transaction == journal->j_running_transaction) {
            jh->b_transaction = NULL;
            jh->b_frozen = 0;
        } else if (jh->b_transaction->t_state == TRANSACTION_COMMIT) {
            jh->b_transaction = NULL;
            jh->b_frozen = 0;
        } else {
            jbd_list_del(&jh->b_transaction_list);
            jbd_list_add(&jh->b_transaction_list, &journal->j_abort_list);
        }
    }

    if (buffer_dirty(bh))
        mark_buffer_clean(bh);

    jbd_unlock_journal(journal);
    journal_put_jhead(journal, jh);

    return ret;
}
